import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D4CBuebE.js";const p=JSON.parse('{"title":"Privacy Policy","description":"What Tackora collects, why, who processes it, and your choices.","frontmatter":{"title":"Privacy Policy","description":"What Tackora collects, why, who processes it, and your choices.","aside":false},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md","lastUpdated":1790885967000}'),s={name:"privacy.md"};function n(i,e,c,h,l,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to &quot;Privacy Policy&quot;">​</a></h1><p><em>Last updated 1 October 2026</em></p><p>This policy explains what Cyberia AI Studio, Tunisia (&quot;we&quot;, &quot;us&quot;), the maker of Tackora, collects when you use the Tackora website, web app and runner, why, and what you can do about it.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to &quot;The short version&quot;">​</a></h2><ul><li>Your code stays on your machines. Agents run there; we never clone or store your repositories.</li><li>We keep what the board needs: your account, your organization, tickets, conversations and the logs of each run.</li><li>We don&#39;t sell your data, don&#39;t use it to train models, and don&#39;t show ads.</li></ul><h2 id="what-we-collect" tabindex="-1">What we collect <a class="header-anchor" href="#what-we-collect" aria-label="Permalink to &quot;What we collect&quot;">​</a></h2><p><strong>Account.</strong> When you sign in with GitHub we receive your name, username, email address and avatar. We use them to identify you and to show you to your teammates.</p><p><strong>Organization.</strong> Its name, its members and their roles, and pending invitations (the invited email address).</p><p><strong>Board content.</strong> Tickets (title, description, notes, status, branch and pull request links), conversations with agents, your answers to their requests, the problems agents report, and images you attach to messages.</p><p><strong>Run logs.</strong> As an agent works, your runner sends the run&#39;s messages, tool calls and command output so you can follow it. Secrets the runner recognizes are masked on your machine before anything is sent. Run logs are kept for 30 days.</p><p><strong>Runners.</strong> For each machine you connect: its name, operating system, runner version, the agents installed, the repositories&#39; remote addresses and default branches, and when it was last seen. We also keep a one-way hash of the machine&#39;s id so signing in again on the same machine replaces its old runner instead of adding a duplicate.</p><p><strong>Usage.</strong> For each run: when it started and ended, the agent, model and effort, lines changed, and the tokens and cost the agent reports, so your organization can see where agent time goes.</p><p><strong>Technical data.</strong> Standard server logs (IP address, browser, time and the page requested) for security and to fix problems, kept for up to 30 days.</p><p><strong>In your browser.</strong> The web app keeps your sign-in tokens and small preferences (the last organization you used, tickets you opened recently) in your browser&#39;s local storage. We don&#39;t use advertising or tracking cookies.</p><h2 id="what-we-don-t-collect" tabindex="-1">What we don&#39;t collect <a class="header-anchor" href="#what-we-don-t-collect" aria-label="Permalink to &quot;What we don&#39;t collect&quot;">​</a></h2><p>Your repositories&#39; contents, your files, your agents&#39; credentials or API keys, and anything on your machines that the runner doesn&#39;t send as part of a run log.</p><h2 id="why-we-use-it" tabindex="-1">Why we use it <a class="header-anchor" href="#why-we-use-it" aria-label="Permalink to &quot;Why we use it&quot;">​</a></h2><p>To run the Service for you and your organization; to send the emails you&#39;d expect (invitations, an agent needing a person, billing); to keep the Service secure; and, for paid plans, to bill you. We rely on our agreement with you to provide the Service, and on our legitimate interest in keeping it secure and working.</p><h2 id="who-processes-it-for-us" tabindex="-1">Who processes it for us <a class="header-anchor" href="#who-processes-it-for-us" aria-label="Permalink to &quot;Who processes it for us&quot;">​</a></h2><ul><li><strong>Railway</strong> hosts our servers and database.</li><li><strong>GitHub</strong> handles sign-in when you choose it.</li><li><strong>Loops</strong> sends our emails.</li><li><strong>Stripe</strong> processes payments for paid plans.</li></ul><p>Each only receives what it needs for that job. Your data may be processed in the United States and other countries where these providers operate, under their data protection terms.</p><h2 id="how-long-we-keep-it" tabindex="-1">How long we keep it <a class="header-anchor" href="#how-long-we-keep-it" aria-label="Permalink to &quot;How long we keep it&quot;">​</a></h2><p>Run logs: 30 days. Server logs: up to 30 days. Everything else: while your account or organization exists. When you delete an organization or your account, its data is deleted within 30 days, apart from records we must keep by law (such as invoices).</p><h2 id="your-choices-and-rights" tabindex="-1">Your choices and rights <a class="header-anchor" href="#your-choices-and-rights" aria-label="Permalink to &quot;Your choices and rights&quot;">​</a></h2><p>You can see and edit your content in the app, export it, and delete tickets, repositories, your organization or your account. You can ask us for a copy of your personal data, to correct it, to delete it, or to stop processing it, and you can complain to your data protection authority. Write to us at the address below to use these rights.</p><h2 id="children" tabindex="-1">Children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;Children&quot;">​</a></h2><p>The Service is not for anyone under 16.</p><h2 id="changes" tabindex="-1">Changes <a class="header-anchor" href="#changes" aria-label="Permalink to &quot;Changes&quot;">​</a></h2><p>If we change this policy in a way that matters, we&#39;ll post it here and tell account holders by email before it applies.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Cyberia AI Studio, Tunisia, is responsible for your data. Privacy questions or requests: <a href="mailto:anas.bassoumi@gmail.com" target="_blank" rel="noreferrer">anas.bassoumi@gmail.com</a>. We answer within 30 days.</p>',31)])])}const y=a(s,[["render",n]]);export{p as __pageData,y as default};
